MERGE INTO SCM_MGR.SCM_ADM_API_M T USING (
  SELECT 'DMF0040_titleSet_SAVE' API_ID, 'PROC_SAVE' API_TP_CD, 'MSG_API_DMF0040_titleSet_SAVE' API_MSG_ID,
         'DMF0040 Column/Measure TitleSet 영구 저장' API_MSG_DESC, 'SCM0002_SET_TITLESET_POPUP' API_URL FROM DUAL
  UNION ALL
  SELECT 'DMF0040_titleSet_SEARCH', 'PROC_SELECT', 'MSG_API_DMF0040_titleSet_SEARCH',
         'DMF0040 TitleSet 조회', 'DMF0002_GET_TITLESET_POPUP' FROM DUAL
) S ON (T.API_ID = S.API_ID)
WHEN MATCHED THEN UPDATE SET T.API_TP_CD=S.API_TP_CD, T.API_URL=S.API_URL, T.USE_YN='Y', T.LAST_UPDATED_BY='admin', T.LAST_UPDATE_DATE=SYSDATE
WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_MSG_DESC, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES (S.API_ID, S.API_TP_CD, S.API_MSG_ID, S.API_MSG_DESC, S.API_URL, 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

